edits.replacement:
  #partymodal textarea{ font-size:13px; word-break:break-all; }
/* v28.xx (cw-uc-lines) b-31 step 7, critic on 05/06/07 (explaining paragraphs, 13px text in an empty card): sector surface and weather hint lines hidden, party and terms text scaled to 18px. */
#root #condhint, #root #wxhint{ display:none !important; }
#root #partymodal .msub, #root #partymodal .hint, #root #termsmodal .msub{ font-size:18px; line-height:1.4; }
#root #partymodal textarea{ font-size:16px; }
#root #termsmodal .plist{ font-size:18px; }

check:
{v:'VER',what:'party intro is one short line, sector hint lines hidden, party text 18px',
 run:function(){
   var bad=[];
   try{
     var pm=document.getElementById('partymodal'), m=pm&&pm.querySelector('.msub');
     if(!m||m.textContent.length>60) bad.push('party intro long: '+(m&&m.textContent.length));
     var t=document.getElementById('partytrade');
     if(!t||t.textContent.length>80) bad.push('trade line long');
     ['condhint','wxhint'].forEach(function(id){ var e=document.getElementById(id);
       if(!e) bad.push('no '+id); else if(getComputedStyle(e).display!=='none') bad.push(id+' displays'); });
     var fs=m?parseFloat(getComputedStyle(m).fontSize):0;
     if(fs<18) bad.push('party msub '+fs+'px');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   return bad.length?bad.join('; '):null; }},
